begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.prove(result text) returns void language plpgsql as $$begin
 if result not like 'ok %' then raise exception 'Hosted reconciliation proof failed: %',result;end if;
 perform set_config('lrv.recon_checks',(coalesce(nullif(current_setting('lrv.recon_checks',true),''),'0')::integer+1)::text,true);
end $$;
create temp table recon_fixture(key text primary key,value jsonb);
grant all on recon_fixture to authenticated,service_role;
insert into recon_fixture values('actor',to_jsonb(gen_random_uuid())),('session',to_jsonb(gen_random_uuid())),('first',to_jsonb(gen_random_uuid())),('second',to_jsonb(gen_random_uuid()));
insert into auth.users(id,email,raw_user_meta_data)select (value#>>'{}')::uuid,'synthetic-reconciliation-'||(value#>>'{}')||'@example.test','{}'from recon_fixture where key='actor';
update profiles set is_active=true,full_name='Synthetic rollback reviewer'where id=(select (value#>>'{}')::uuid from recon_fixture where key='actor');
insert into user_roles(user_id,role)select (value#>>'{}')::uuid,'ADMIN'from recon_fixture where key='actor'on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)select (select (value#>>'{}')::uuid from recon_fixture where key='session'),(select (value#>>'{}')::uuid from recon_fixture where key='actor'),now(),now();
create function pg_temp.actor()returns void language plpgsql as $$begin
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',(select value#>>'{}'from recon_fixture where key='actor'),'session_id',(select value#>>'{}'from recon_fixture where key='session'))::text,true);
end $$;
create function pg_temp.review(v integer,on_policy boolean)returns jsonb language plpgsql as $$declare action uuid:=gen_random_uuid();q jsonb;begin
 q:=jsonb_build_object('expected_version',v,'enabled',on_policy,'window_from',case when on_policy then clock_timestamp()-interval '1 hour'end,'window_until',case when on_policy then clock_timestamp()+interval '1 day'end,'review_note','Synthetic bounded rollback-only review','attest_review',true);
 perform prepare_operational_review(auth.uid(),action,'reconciliation_policy',q);return execute_operational_review(auth.uid(),action);
end $$;
select pg_temp.prove(is((select count(*)from operational_reconciliation_policy),0::bigint,'Migration does not seed activation'));
select pg_temp.prove(is((select count(*)from operational_reconciliation_cursor),0::bigint,'Migration does not seed cursor'));
select pg_temp.prove(is((select active from cron.job where jobname='reconcile-operational-tasks'),false,'Cron installed inactive'));
select pg_temp.prove(is((select schedule from cron.job where jobname='reconcile-operational-tasks'),'*/5 * * * *','Five-minute timetable'));
select pg_temp.prove(is(scheduler_dispatch('reconcile-operational-tasks')->>'outcome','disabled','Default-off dispatch before Vault'));
select pg_temp.prove(ok(not has_function_privilege('anon','recover_operational_reconciliation_run(uuid,integer)','EXECUTE'),'No anonymous run discovery'));
select pg_temp.prove(ok(not has_function_privilege('authenticated','execute_operational_reconciliation_run(uuid,integer)','EXECUTE'),'No staff worker execution'));
select pg_temp.prove(ok(not has_function_privilege('service_role','execute_operational_review(uuid,uuid)','EXECUTE'),'Service cannot attest checklist work'));
select pg_temp.prove(ok(not has_function_privilege('service_role','scheduler_dispatch_operational_reconciliation()','EXECUTE'),'No service cron wrapper'));
select pg_temp.prove(ok(not has_function_privilege('service_role','operational_reconciliation_source(text,uuid)','EXECUTE'),'No direct materializer bypass'));
select pg_temp.prove(ok(relrowsecurity and not has_table_privilege('anon',oid,'SELECT')and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('service_role',oid,'INSERT'),relname||' RLS and private grants'))from pg_class where relnamespace='public'::regnamespace and relname in('operational_reconciliation_policy','operational_reconciliation_runs','operational_reconciliation_results','operational_reconciliation_cursor');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.prove(is(start_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),1),'{"disabled":true}'::jsonb,'Off service creates no run'));
set local role authenticated;select pg_temp.actor();
select pg_temp.prove(is(read_operational_reconciliation_policy(),null::jsonb,'Reviewer sees off policy'));
select pg_temp.prove(is(read_operational_reconciliation_status()->>'cron_active','false','Reviewer sees inactive cron'));
select pg_temp.prove(is(pg_temp.review(null,true)->>'version','1','Exact reviewer activates transient policy'));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into recon_fixture select 'started',start_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),1);
select pg_temp.prove(is((select value->>'outcome'from recon_fixture where key='started'),'started','Run reserves original request'));
select pg_temp.prove(is((select value->'counts'from recon_fixture where key='started'),'null'::jsonb,'Started counts stay unknown'));
select pg_temp.prove(is(recover_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),1),(select value from recon_fixture where key='started'),'Read-only exact start recovery'));
select pg_temp.prove(throws_ok($q$select start_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),2)$q$,'23505',null,'Changed limit collides'));
select pg_temp.prove(throws_ok($q$select start_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='second'),1)$q$,'PT409',null,'Successor cannot hide unresolved run'));
set local role authenticated;select pg_temp.actor();select pg_temp.review(1,false);
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into recon_fixture select 'paused',execute_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),1);
select pg_temp.prove(is((select value->>'outcome'from recon_fixture where key='paused'),'paused','Gate change pauses original run'));
select pg_temp.prove(is((select value->'counts'from recon_fixture where key='paused'),'null'::jsonb,'Paused work reports no committed counts'));
select pg_temp.prove(is((select value->'checkpoint'from recon_fixture where key='paused'),'null'::jsonb,'Pause cannot advance checkpoint'));
select pg_temp.prove(is(recover_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='first'),1),(select value from recon_fixture where key='paused'),'Recovery survives changed gate'));
set local role authenticated;select pg_temp.actor();select pg_temp.review(2,true);
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select start_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='second'),1);
insert into recon_fixture select 'completed',execute_operational_reconciliation_run((select (value#>>'{}')::uuid from recon_fixture where key='second'),1);
select pg_temp.prove(is((select value->>'outcome'from recon_fixture where key='completed'),'completed','Bounded genuine database batch commits inside rollback transaction'));
select pg_temp.prove(ok((select(value#>>'{counts,examined}')::integer<=1 from recon_fixture where key='completed'),'Source limit obeyed'));
select pg_temp.prove(is((select value#>>'{checkpoint,version}'from recon_fixture where key='completed'),'1','Exactly one checkpoint advancement'));
select pg_temp.prove(is(execute_operational_reconciliation_run((select(value#>>'{}')::uuid from recon_fixture where key='second'),1),(select value from recon_fixture where key='completed'),'Terminal replay never materializes again'));
select pg_temp.prove(ok(not (select value ?|array['patient','client','source_snapshot','checklist']from recon_fixture where key='completed'),'Receipt contains no source snapshots'));
set local role authenticated;select pg_temp.actor();select pg_temp.review(3,false);
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.prove(is(recover_operational_reconciliation_run((select(value#>>'{}')::uuid from recon_fixture where key='second'),1),(select value from recon_fixture where key='completed'),'Completed recovery independent of current gates'));
reset role;
select pg_temp.prove(is((select count(*)from operational_reconciliation_results),2::bigint,'Exactly one terminal result per UUID'));
select pg_temp.prove(is((select pending_run_id from operational_reconciliation_cursor),null::uuid,'All transient reservations resolved'));
select pg_temp.prove(is(scheduler_dispatch('reconcile-operational-tasks')->>'outcome','disabled','Paused policy creates no transport'));
select jsonb_build_object('checks',current_setting('lrv.recon_checks')::integer,'provider_requests',0,'rollback_only',true)as proof;
rollback;
